<!doctype html><html><head><meta charset="utf-8"><title>Account statement</title><style>body{font-family:Arial,sans-serif;color:#17243a;margin:32px}.head{display:flex;justify-content:space-between;border-bottom:2px solid #1769ff;padding-bottom:18px}.summary{display:flex;gap:30px;margin:24px 0}.summary div{border:1px solid #dce5ef;padding:12px 18px;border-radius:8px}table{width:100%;border-collapse:collapse;font-size:12px}th,td{border-bottom:1px solid #dce5ef;padding:9px;text-align:left}th{background:#eef5ff}.debit{color:#b42335}.credit{color:#087946}@media print{button{display:none}body{margin:12mm}}</style></head><body><button onclick="print()">Print</button><div class="head"><div><h1>Account statement</h1><strong>{{ auth()->user()->name }}</strong><div>{{ auth()->user()->email }}</div></div><div>{{ now()->format('Y-m-d H:i') }}</div></div><div class="summary"><div>Opening<br><strong>${{ number_format((float)$opening,2) }}</strong></div><div>Credits<br><strong class="credit">${{ number_format((float)$summary['income'],2) }}</strong></div><div>Debits<br><strong class="debit">${{ number_format((float)$summary['expense'],2) }}</strong></div><div>Refunds<br><strong>${{ number_format((float)$summary['refund'],2) }}</strong></div></div><table><thead><tr><th>Date</th><th>Description</th><th>Reference</th><th>Debit</th><th>Credit</th><th>Balance</th></tr></thead><tbody>@forelse($transactions as $row)<tr><td>{{ $row->created_at->format('Y-m-d H:i') }}</td><td>{{ $row->note ?: str($row->kind)->replace('_',' ')->title() }}</td><td>{{ $row->reference ?: '—' }}</td><td class="debit">{{ $row->direction==='expense'?'$'.number_format((float)$row->amount,2):'—' }}</td><td class="credit">{{ $row->direction==='income'?'$'.number_format((float)$row->amount,2):'—' }}</td><td>${{ number_format((float)$row->balance_after,2) }}</td></tr>@empty<tr><td colspan="6">No movements.</td></tr>@endforelse</tbody></table></body></html>
